{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "Workload_Audit_Identity_Map",
  "type": "object",
  "properties": {
    "audit_metadata": {
      "type": "object",
      "properties": {
        "mode": { "const": "bijective_identity_mapping" },
        "heuristic_suppression": { "const": "MAXIMAL" }
      }
    },
    "workload_entries": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "teacher_id": { "type": "string" },
          "assigned_locations": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "room_type": { "enum": ["Classroom", "ISS_Bathroom", "Shared_Bathroom", "Other"] },
                "room_identifier": { "type": "string", "description": "Unique name/number - DO NOT MERGE" },
                "invariants": {
                  "type": "object",
                  "properties": {
                    "trash_bins": { "type": "integer" },
                    "carpet_count": { "type": "integer" },
                    "is_shared": { "type": "boolean" }
                  },
                  "required": ["trash_bins", "carpet_count", "is_shared"]
                }
              },
              "required": ["room_type", "room_identifier", "invariants"]
            }
          },
          "labor_hours": { "type": "number", "description": "Exact decimal hours" }
        },
        "required": ["teacher_id", "assigned_locations", "labor_hours"]
      }
    }
  },
  "required": ["audit_metadata", "workload_entries"]
}
